export function c015(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalFlange(context, id + "flange1", { "edges" : atFraction(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE, 1, 0.5, 1), "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 15 * millimeter, "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree, "autoMiter" : true, "useDefaultRadius" : true });
    const t1 = newSketchOnPlane(context, id + "t1", { "sketchPlane" : plane(vector(40, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skRectangle(t1, "r1", { "firstCorner" : vector(10, 14) * millimeter, "secondCorner" : vector(20, 22) * millimeter });
    skSolve(t1);
    sheetMetalTab(context, id + "tab1", { "tabFaces" : qSketchRegion(id + "t1"), "booleanUnionScope" : atFraction(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE, 1, 0.5, 0.8), "booleanOffset" : 0 * millimeter });
    return { "counts" : bodyCounts(context), "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

// sheet-metal-flange: a 40 × 30 plate: a partial flange on its right edge, 5 mm in from each end, holding the adjacent edges (the default)
export function c016(context is Context, id is Id)
