    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalFlange(context, id + "flange1", { "edges" : atFraction(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE, 1, 0.5, 1), "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 15 * millimeter, "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree, "autoMiter" : true, "useDefaultRadius" : true, "isPartialFlange" : true, "chainType" : SMPartialFlangeChainType.PER_EDGE, "flipFlangeBounds" : false, "holdAdjacentEdges" : true, "firstBoundType" : SMFlangeBoundingType.BLIND, "firstBoundOffset" : 5 * millimeter, "hasSecondBound" : true, "secondBoundType" : SMFlangeBoundingType.BLIND, "secondBoundOffset" : 5 * millimeter });
    return { "counts" : bodyCounts(context), "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
