// sheet-metal-rip: a 40 × 30 plate whose long edges are each two lines meeting at x = 20, ripped across between those vertices (default gap)
export function c017(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(20, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(20, 0) * millimeter, "end" : vector(40, 0) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(40, 0) * millimeter, "end" : vector(40, 30) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(40, 30) * millimeter, "end" : vector(20, 30) * millimeter });
    skLineSegment(s1, "l5", { "start" : vector(20, 30) * millimeter, "end" : vector(0, 30) * millimeter });
    skLineSegment(s1, "l6", { "start" : vector(0, 30) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalRip(context, id + "rip1", { "vertices" : qUnion([qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(20, 0, 2) * millimeter), qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(20, 30, 2) * millimeter)]), "useDefaultGap" : true });
    return { "counts" : bodyCounts(context), "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

// extrude: a 20 × 10 rectangle on the xy plane extruded 10 mm, starting 5 mm below it
export function c018(context is Context, id is Id)
{
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(e1, "r1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(e1);
    extrude(context, id + "ext1", { "entities" : qSketchRegion(id + "e1"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false, "startOffset" : true, "startOffsetBound" : StartOffsetType.BLIND, "startOffsetDistance" : 5 * millimeter, "startOffsetOppositeDirection" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "ext1", EntityType.BODY), BodyType.SOLID)) };
}

// extrude: the same, starting from the top of a separate block 8 mm high
export function c019(context is Context, id is Id)
{
    const refSketch = newSketchOnPlane(context, id + "refSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(refSketch, "rect1", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(refSketch);
    extrude(context, id + "ref", { "entities" : qSketchRegion(id + "refSketch"), "endBound" : BoundingType.BLIND, "depth" : 8 * millimeter });
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(e1, "r1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(e1);
    extrude(context, id + "ext1", { "entities" : qSketchRegion(id + "e1"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false, "startOffset" : true, "startOffsetBound" : StartOffsetType.ENTITY, "startOffsetEntity" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "ref", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(0, 0, 8) * millimeter) });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "ext1", EntityType.BODY), BodyType.SOLID)) };
}

// extrude: the same, starting from the top edge of a cylinder (radius 5 about (40, 0), 12 tall)
export function c020(context is Context, id is Id)
{
    const refSketch = newSketchOnPlane(context, id + "refSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(refSketch, "circle1", { "center" : vector(40, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(refSketch);
    extrude(context, id + "ref", { "entities" : qSketchRegion(id + "refSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(e1, "r1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(e1);
    extrude(context, id + "ext1", { "entities" : qSketchRegion(id + "e1"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false, "startOffset" : true, "startOffsetBound" : StartOffsetType.ENTITY, "startOffsetEntity" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "ref", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(45, 0, 12) * millimeter) });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "ext1", EntityType.BODY), BodyType.SOLID)) };
}

// edit-curve: a spline through four points in space flattened onto its best-fit plane
export function c021(context is Context, id is Id)
{
    opFitSpline(context, id + "spline1", { "points" : [vector(0, 0, 0) * millimeter, vector(10, 5, 3) * millimeter, vector(20, 0, -2) * millimeter, vector(30, 8, 4) * millimeter] });
    editCurve(context, id + "edit1", { "wire" : qCreatedBy(id + "spline1", EntityType.BODY), "approximate" : false, "elevate" : false, "planarize" : true, "planeReference" : PlaneReference.BEST, "editControlPoints" : false, "showDetails" : false, "approximationShowDeviation" : false, "lockEnds" : false });
    return { "curve" : curveProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id + "spline1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)) };
}

