// evaluate: the planes of a fillet's arc, a hole's circle, a top face's loop and a straight edge; rays through the part; the fillet's curvatures and radius
export function c023(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20, 0, 20) * millimeter), "radius" : 5 * millimeter });
    const h1 = newSketchOnPlane(context, id + "h1", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(h1, "c1", { "center" : vector(20, 15) * millimeter, "radius" : 4 * millimeter });
    skSolve(h1);
    extrude(context, id + "hole", { "entities" : qSketchRegion(id + "h1"), "endBound" : BoundingType.THROUGH_ALL, "oppositeDirection" : true, "operationType" : NewBodyOperationType.REMOVE, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    return { "arc" : planarProbe(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(0, 1.464466, 18.535534) * millimeter), false), "circle" : planarProbe(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(24, 15, 20) * millimeter), false), "loop" : planarProbe(context, qAdjacent(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 25, 20) * millimeter), AdjacencyType.EDGE, EntityType.EDGE), true), "line" : planarProbe(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(40, 15, 0) * millimeter), false), "rays" : rayProbe(context, { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "ray" : line(vector(20, -10, 10) * millimeter, vector(0, 1, 0)), "closest" : false }), "closest" : rayProbe(context, { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "ray" : line(vector(20, -10, 10) * millimeter, vector(0, 1, 0)) }), "behind" : rayProbe(context, { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "ray" : line(vector(20, 15, 10) * millimeter, vector(0, 1, 0)), "closest" : false, "includeIntersectionsBehind" : true }), "curvatures" : mapArray(evFaceCurvatures(context, { "face" : qCreatedBy(id + "fillet1", EntityType.FACE), "parameters" : [vector(0, 0), vector(0.5, 0.5), vector(1, 1)] }), function(c) { return { "min" : roundToPrecision(c.minCurvature * millimeter, 6), "max" : roundToPrecision(c.maxCurvature * millimeter, 6), "minDirection" : dir6(c.minDirection), "maxDirection" : dir6(c.maxDirection) }; }), "radius" : roundToPrecision(evFilletRadius(context, { "face" : qCreatedBy(id + "fillet1", EntityType.FACE) }) / millimeter, 6) };
}
